{"cmd":"python - <<'PY'
import json, pandas as pd

data=json.load(open('benchmark/source_data.json'))
# Build dataframe: year, pen_avg, branch_idx, licenses_total
from collections import defaultdict
pen=defaultdict(float); pen_n=defaultdict(int)
for r in data['digital_payment_penetration']['data']:
    pen[r['year']]+=r['penetration_pct']; pen_n[r['year']]+=1
pen={y:pen[y]/pen_n[y] for y in pen}
branches=defaultdict(float)
for r in data['traditional_bank_branches']['data']:
    branches[r['year']]+=r['branches_k']
base=branches[2015]
branch_idx={y:branches[y]/base*100 for y in branches}
licenses=defaultdict(float)
for r in data['digital_bank_licenses']['data']:
    licenses[r['year']]+=r['cumulative_licenses']

rows=[]
for y in sorted(branches):
    rows.append({'year':y,'Digital payment penetration (avg %)':pen[y], 'Branch footprint (2015=100)':branch_idx[y], 'Digital bank licenses (cumulative, total)':licenses[y]})
print(pd.DataFrame(rows).to_string(index=False))
PY"}
